SELECT COUNT(*) 
FROM ratings 
WHERE userId = 42;

SELECT COUNT(*) 
FROM movies 
WHERE genres = 'Comedy';

SELECT COUNT(*) 
FROM ratings 
WHERE rating = 5.0;

SELECT tmdbId
FROM links
WHERE movieId = 1;

SELECT AVG(rating) 
FROM ratings 
WHERE movieId = (SELECT movieId FROM movies WHERE title = 'Toy Story (1995)');

SELECT COUNT(*) 
FROM movies 
WHERE title LIKE '%1995%';

SELECT COUNT(DISTINCT movieId)
FROM tags
WHERE userId = 123;

SELECT COUNT(DISTINCT movieId)
FROM movies
WHERE genres LIKE '%Horror%';

SELECT COUNT(*)
FROM movies
WHERE genres = '';

SELECT COUNT(*) 
FROM ratings 
WHERE strftime('%Y', timestamp) = '2015';

SELECT title
FROM movies
WHERE movieId NOT IN (SELECT movieId FROM tags);

SELECT (strftime('%Y', 'now') - strftime('%Y', user_create_time)) AS age
FROM users
WHERE userId = 42;
